let training=read(r("training-audit.json"));assert_eq!(training["passed"],true);assert_eq!(training["SDK_prove_count"],99);assert_eq!(training["SDK_load_count"],0);assert_eq!(training["SDK_constructor_count"],0);assert_eq!(training["proof_ledger"],30052);let ledger:BTreeSet<String>=serde_json::from_value(read(r("proof-sha256-after.json"))).unwrap();let prior:BTreeSet<String>=serde_json::from_value(read(r("prior-proof-sha256.json"))).unwrap();assert_eq!(ledger.len(),30052);assert_eq!(prior.len(),29953);assert!(prior.is_subset(&ledger));let inventory=read(r("training-proof-inventory.json"));assert_eq!(inventory.as_object().unwrap().len(),198);let proof_hashes=inventory.as_object().unwrap().iter().filter(|(p,_)|p.ends_with(".proof")).map(|(p,h)|{assert_eq!(hash(p),h.as_str().unwrap());h.as_str().unwrap().to_string()}).collect::<BTreeSet<_>>();assert_eq!(proof_hashes,ledger.difference(&prior).cloned().collect());let functions=read(r("profile-functions.json"));let selected=read(r("hot-profile-records.json"));let mut hot=BTreeMap::new();for records in selected.as_object().unwrap().values(){for(k,v)in records.as_object().unwrap(){assert_eq!(functions[k],*v);assert!(v["max_block_count"].as_u64().unwrap()>0);hot.insert(k.clone(),v.clone());}}for(raw,p)in functions.as_object().unwrap(){let n=p["demangled"].as_str().unwrap();if p["max_block_count"].as_u64().unwrap()>0&&(n.starts_with("zopro_core::msm::stream_g1_impl")||n.starts_with("zopro_core::msm_affine::borrowed_pending::balanced::feed")||n=="<zopro_zolana::Prover>::prove"){hot.insert(raw.clone(),p.clone());}}
for prefix in["zopro_core::msm::stream_g1_impl","zopro_core::msm_affine::borrowed_pending::balanced::feed","<zopro_zolana::Prover>::prove"]{assert!(hot.values().any(|p|p["demangled"].as_str().unwrap().starts_with(prefix)));}let mut warnings=Vec::new();let mut missing=Vec::new();let mut mismatches=Vec::new();for step in["candidate-field-mode1","candidate-core-mode0","candidate-core-mode1","candidate-prover-mode0","candidate-prover-mode1","libraries-candidate","candidate"]{let text=fs::read_to_string(r(format!("native-use/{step}/stderr.log"))).unwrap();for line in text.lines(){if line.contains("no profile data available"){warnings.push(json!({"step":step,"line":line}));if step=="candidate"||step=="libraries-candidate"{for(raw,p)in&hot{if line.contains(raw.rsplit(';').next().unwrap()){missing.push(json!({"step":step,"line":line,"record":p}));}}}}if line.contains("profile data may be out of date")||line.contains("hash mismatch"){mismatches.push(json!({"step":step,"line":line}));}}}assert!(missing.is_empty());assert!(mismatches.is_empty());let mut binaries=BTreeMap::new();fs::create_dir(r("code-audit")).unwrap();for(stage,label,gen)in[("native","generate",true),("native-use","candidate",false)]{let info=read(r(format!("{stage}/{label}/artifacts.json")));let binary=info["binary"].as_str().unwrap();assert_eq!(hash(binary),info["binary_sha256"]);let command=read(r(format!("{stage}/{label}/command.json")));let argv=command["argv"].as_array().unwrap();for flag in["-O","target-cpu=native","lto=fat","codegen-units=1"]{assert!(argv.contains(&json!(flag)));}assert!(argv.iter().any(|v|v.as_str().is_some_and(|s|s.starts_with(if gen{"profile-generate="}else{"profile-use="}))));if !gen{assert!(!argv.iter().any(|v|v.as_str().is_some_and(|s|s.starts_with("profile-generate="))));}let out=Command::new("nm").args(["--defined-only",binary]).output().unwrap();assert!(out.status.success());let text=String::from_utf8(out.stdout).unwrap();let out=Command::new("readelf").args(["-SW",binary]).output().unwrap();assert!(out.status.success());let sections=String::from_utf8(out.stdout).unwrap();if gen{assert!(text.contains("__llvm_profile_dump")&&text.contains("__llvm_profile_reset_counters"));}else{assert!(!text.contains("__llvm_profile")&&!text.contains("__llvm_prf"));assert!(!sections.contains("__llvm_prf")&&!sections.contains("__llvm_cov"));}fs::write(r(format!("code-audit/{label}-nm.txt")),&text).unwrap();fs::write(r(format!("code-audit/{label}-sections.txt")),&sections).unwrap();binaries.insert(label,info);}
